$(function() {
    ///Start Block////////

    $(document).on("change", ".check-fullday", function (e) {
        var obj = $(this), date = obj.val(), action = 'release-room',
            tempid = $('#tempid').val();

        if (obj.prop('checked')) {
            action = 'hold-room';
            $("input.check-fullday:checkbox[value="+date+"]").prop('checked',true);
        } else {
            $("input.check-fullday:checkbox[value="+date+"]").prop('checked',false);
        }

        $.ajax({
            type: "GET",
            url: '/room/block/actionfullday',
            global:false,
            data: {
                'date': date,
                'tempid': tempid,
                'action': action
            },
            dataType: 'JSON',
            success: function (result) {
                if(result.status == '1') {
                    setTimeout(roomBlockReload, 10);
                }else {
                    alert(result.message);
                    if(result.status == '0') {
                        reload();
                    }else {
                        setTimeout(roomBlockReload, 10);
                    }
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });

    })


    $(document).on("submit", "form#block-room-load-to-grid", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var form = $(this);
        var url = form.attr('action');
        var panel = form.closest('.panel');
        var tempid = $('#tempid').val();
        var fullday = [];
        if($('input.check-fullday:checkbox:checked').length > 0) {
            $("input.check-fullday:checkbox:checked").each(function (i) {
                fullday[i] = $(this).val();
            });
            //alert(fullday.join())
        }
        $('#reservationgrid').html('');

        $.ajax({
            type: "POST",
            url: url,
            data: form.serialize()+'&check_fullday='+fullday.join(), // serializes the form's elements.
            dataType:'JSON',
            global: false,
            success: function(result)
            {
                $('#roomgrid-panel').html(result.content);
                $('#room-action-panel').html(result.action).show();
                if(result.status == '1') {
                    //alert(result.content);
                    var roomtable = $('#roomgrid-panel').find('#roomgrid');
                    roomtable.find('td.active-room').each(function (i) {
                        var td = $(this);
                        var tdaction = td.data('action');
                        if (tdaction == 'hold-room') {
                            $(this).html('<a class="btn btn-success block-room-action" data-action="hold-room" title="HOLD ROOM FOR BLOCK"><i class="fas fa-bed fa-lg text-light"></i></a>');
                        } else if (tdaction == 'release-room') {
                            var tdtempid = td.data('tempid');
                            // if(tempid == tdtempid) {
                            $(this).html('<a class="btn btn-warning block-room-action" data-action="release-room" title="RELEASE ROOM"><i class="fas fa-ban fa-lg text-light"></i></a>');
                            // } else {
                            //     td.addClass('bg-warning').attr('title','HOLD BY '+td.data('user')+' FROM '+td.data('from'));
                            // }
                        }
                    });
                    var table = roomtable.DataTable({
                        scrollY: window.screen.height - 350 + "px",
                        scrollX: true,
                        scrollCollapse: true,
                        paging: false,
                        searching: false,
                        ordering: false,
                        info: false,
                        fixedColumns: {
                            leftColumns: 2
                        }
                    });
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });


    $(document).on("click", ".block-room-action", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var obj = $(this);
        var table = obj.closest('#roomgrid');
        var tempid = $('#tempid').val();
        var url = table.data('action');
        var td = obj.closest('td');
        var date = td.data('date');
        var room = td.closest('tr').data('room');
        var action = obj.data('action');

        if(td.data('backdated') == 'YES') {
            alert('NO ACTION IS POSSIBLE ON BACKDATED ROOM STOCK');
        } else {
            td.html('<i class="fas fa-circle-notch fa-spin fa-3x"></i>');
            $.ajax({
                type: "GET",
                url: url,
                global: false,
                data: {
                    'date': date,
                    'roomno': room,
                    'tempid': tempid,
                    'action': action
                },
                dataType: 'JSON',
                success: function (result) {
                    if (result.status == '1' || result.status == '2') {
                        $('#tempid').val(result.tempid)
                        td.attr('data-tempid', result.tempid);
                        td.html(result.message);
                        $('#room-action-panel').html(result.action).show();
                        if(result.status == '1') {
                            $('#block-action-panel').show();
                        } else {
                            $('#block-action-panel').hide();
                        }
                        $('#timer').timer('reset');
                    } else {
                        alert(result.message);
                        roomBlockReload();
                    }
                },
                error: function (data) {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        }
    });

    /**
     * Save Room Block/Release
     */
    $(document).on("click", "#save-block-release", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var obj = $(this);
        var action = obj.data('action');
        var url = obj.data('url');
        var tempid = $('#tempid').val();
        var note = $('#note').val();

        if (tempid == '0') {
            alert('PLEASE SELECT ROOMS FIRST');
        } else if (note == '') {
            alert('PLEASE ENTER NOTE');
            $('#note').focus();
        } else {
            var data = {
                'action': action,
                'tempid': tempid,
                'note': note,
                'status': action
            };
            $.ajax({
                type: "GET",
                url: url,
                data: data,
                dataType: 'JSON',
                success: function (result) {
                    if (result.status == '1') {
                        /**
                         * Code [1:Reservation Added]
                         */
                        $('#tempid').val(0);
                        alert(result.message);
                        reload();
                    } else {
                        alert(result.message);
                        roomBlockReload();
                    }
                },
                error: function (data) {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        }
    });
})


function roomBlockReload(){
    if($('form#block-room-load-to-grid').length > 0){
        $('form#block-room-load-to-grid').trigger('submit');
    }
}
